<script lang="ts">
	import { onMount } from 'svelte';
	import type { Session } from '@supabase/supabase-js';
	import { createNPC, listNPCs, updateNPC, type NPC } from '$lib/services/npcApi';
	import { getCompendium, type CompendiumEntry } from '$lib/services/compendiumApi';
	import { request } from '$lib/services/sceneApi';
	let { campaignId, sceneId = null, session, ontokencreated = () => {} }: { campaignId: string; sceneId?: string | null; session: Session; ontokencreated?: () => void } = $props();
	type Sheet = NPC['sheet'];
	const fresh = (): Sheet => ({ hitPointsCurrent: 10, hitPointsMax: 10, armorClass: 10, initiative: 0, size: 1, color: 4921830, imageUrl: '', creatureType: 'Humanoide', challenge: '', speed: '9 m', abilities: { strength: 10, dexterity: 10, constitution: 10, intelligence: 10, wisdom: 10, charisma: 10 }, traits: [], actions: [], resistances: [], immunities: [], senses: '', languages: '' });
	const normalized = (value: Partial<Sheet>): Sheet => ({ ...fresh(), ...value, abilities: { ...fresh().abilities, ...value.abilities }, traits: value.traits ?? [], actions: value.actions ?? [], resistances: value.resistances ?? [], immunities: value.immunities ?? [] });
	let npcs = $state<NPC[]>([]), srdCreatures = $state<CompendiumEntry[]>([]), selected = $state<NPC | null>(null), selectedSRD = $state<CompendiumEntry | null>(null), monsterName = $state(''), sheet = $state<Sheet>(fresh()), loading = $state(true), saving = $state(false), placing = $state<string | null>(null), message = $state('');
	const csv = (value: string) => value.split(',').map((item) => item.trim()).filter(Boolean);
	function edit(npc: NPC) { selected = npc; selectedSRD = null; monsterName = npc.name; sheet = normalized(npc.sheet); message = ''; }
	function viewSRD(entry: CompendiumEntry) { selected = null; selectedSRD = entry; message = ''; }
	function reset() { selected = null; selectedSRD = null; monsterName = ''; sheet = fresh(); message = ''; }
	function addTrait() { sheet.traits = [...sheet.traits, { name: 'Novo traço', description: '' }]; }
	function addAction() { sheet.actions = [...sheet.actions, { name: 'Novo ataque', kind: 'action', toHit: 0, range: '', damage: '', saveDC: 0, description: '' }]; }
	function removeTrait(index: number) { sheet.traits = sheet.traits.filter((_, item) => item !== index); }
	function removeAction(index: number) { sheet.actions = sheet.actions.filter((_, item) => item !== index); }
	async function load() { loading = true; try { const [campaignNPCs, compendium] = await Promise.all([listNPCs(session, campaignId), getCompendium(session, campaignId)]); npcs = campaignNPCs.npcs; const srdSourceIDs = new Set(compendium.sources.filter((source) => source.kind === 'srd' || source.readOnly).map((source) => source.id)); srdCreatures = compendium.entries.filter((entry) => entry.entryType === 'other' && srdSourceIDs.has(entry.sourceId) && (entry.rules.kind === 'monster' || entry.rules.catalog === 'monster')); } catch (error) { message = error instanceof Error ? error.message : 'Não foi possível carregar o bestiário.'; } finally { loading = false; } }
	async function save() { if (!monsterName.trim()) { message = 'Informe o nome da criatura.'; return; } saving = true; message = ''; const payload = { name: monsterName.trim(), sheet: { ...sheet, hitPointsCurrent: Math.min(sheet.hitPointsCurrent, sheet.hitPointsMax) } }; try { const npc = selected ? await updateNPC(session, campaignId, selected.id, payload) : await createNPC(session, campaignId, payload); npcs = selected ? npcs.map((item) => item.id === npc.id ? npc : item) : [...npcs, npc]; edit(npc); message = selected ? 'Criatura atualizada.' : 'Criatura adicionada ao bestiário.'; } catch (error) { message = error instanceof Error ? error.message : 'Não foi possível salvar a criatura.'; } finally { saving = false; } }
	async function place(npc: NPC) { if (!sceneId) { message = 'Abra uma cena na aba Mesa antes de colocar uma criatura.'; return; } placing = npc.id; message = ''; try { await request(session, `/api/v1/scenes/${sceneId}/tokens/from-npc`, { method: 'POST', body: JSON.stringify({ actorId: npc.id }) }); await ontokencreated(); message = `${npc.name} foi adicionado à cena.`; } catch (error) { message = error instanceof Error ? error.message : 'Não foi possível adicionar a criatura.'; } finally { placing = null; } }
	function placeSelected() { if (selected) void place(selected); }
	onMount(() => void load());
</script>

<main class="bestiary">
	<header><div><p>GESTÃO DA CAMPANHA</p><h2>Bestiário</h2><span>Crie fichas privadas de criatura e coloque-as no mapa quando precisar.</span></div><button onclick={reset}>+ Nova criatura</button></header>
	{#if message}<p class:success={message.includes('adicionada') || message.includes('atualizada') || message.includes('adicionado')} class="message">{message}</p>{/if}
	<section class="layout"><aside><h3>Criaturas da campanha</h3>{#if loading}<p>Carregando…</p>{:else if !npcs.length}<p class="hint">Seu bestiário está vazio.</p>{:else}{#each npcs as npc (npc.id)}<button class:active={selected?.id === npc.id} onclick={() => edit(npc)}><strong>{npc.name}</strong><small>{npc.sheet.creatureType || 'Criatura'} · PV {npc.sheet.hitPointsMax} · CA {npc.sheet.armorClass}</small></button>{/each}{/if}<h3 class="srd-heading">Criaturas do SRD</h3>{#if loading}<p>Carregando…</p>{:else if !srdCreatures.length}<p class="hint">Nenhuma criatura SRD disponível.</p>{:else}{#each srdCreatures as creature (creature.id)}<button class:active={selectedSRD?.id === creature.id} onclick={() => viewSRD(creature)}><strong>{creature.translations['pt-BR'] || creature.name}</strong><small>SRD · somente leitura</small></button>{/each}{/if}</aside>
		<section class="editor">{#if selectedSRD}<div class="editor-head"><h3>{selectedSRD.translations['pt-BR'] || selectedSRD.name}</h3><span>CRIATURA DO SRD · SOMENTE LEITURA</span></div><article class="srd-preview"><p>{selectedSRD.summary}</p><small>O conteúdo SRD é separado do bestiário privado da campanha e não pode ser alterado aqui.</small></article>{:else}<div class="editor-head"><h3>{selected ? 'Editar criatura' : 'Nova criatura privada'}</h3><span>{selected ? 'As mudanças afetam novos tokens; tokens já na mesa mantêm o estado atual.' : 'Registre uma ficha compacta e utilizável em combate.'}</span></div><form onsubmit={(event) => { event.preventDefault(); void save(); }}><div class="grid"><label>Nome<input bind:value={monsterName} maxlength="120" placeholder="Ex.: Sentinela da teia"/></label><label>Tipo<input bind:value={sheet.creatureType} maxlength="80" placeholder="Ex.: Humanoide"/></label><label>ND<input bind:value={sheet.challenge} maxlength="20" placeholder="Ex.: 2"/></label><label>Deslocamento<input bind:value={sheet.speed} maxlength="80" placeholder="Ex.: 9 m, escalada 9 m"/></label><label>PV máximo<input bind:value={sheet.hitPointsMax} type="number" min="1" max="9999"/></label><label>PV atual<input bind:value={sheet.hitPointsCurrent} type="number" min="0" max={sheet.hitPointsMax}/></label><label>CA<input bind:value={sheet.armorClass} type="number" min="0" max="99"/></label><label>Iniciativa<input bind:value={sheet.initiative} type="number"/></label><label>Tamanho no grid<input bind:value={sheet.size} type="number" min="1" max="6"/></label><label class="wide">URL da miniatura<input bind:value={sheet.imageUrl} type="url" placeholder="URL pública do Supabase Storage"/></label></div>
		<h4>Atributos</h4><div class="abilities"><label>FOR<input bind:value={sheet.abilities.strength} type="number" min="0" max="30"/></label><label>DES<input bind:value={sheet.abilities.dexterity} type="number" min="0" max="30"/></label><label>CON<input bind:value={sheet.abilities.constitution} type="number" min="0" max="30"/></label><label>INT<input bind:value={sheet.abilities.intelligence} type="number" min="0" max="30"/></label><label>SAB<input bind:value={sheet.abilities.wisdom} type="number" min="0" max="30"/></label><label>CAR<input bind:value={sheet.abilities.charisma} type="number" min="0" max="30"/></label></div>
		<div class="grid"><label>Resistências<input value={sheet.resistances.join(', ')} onchange={(event) => sheet.resistances = csv(event.currentTarget.value)} placeholder="fogo, veneno"/></label><label>Imunidades<input value={sheet.immunities.join(', ')} onchange={(event) => sheet.immunities = csv(event.currentTarget.value)} placeholder="amedrontado"/></label><label>Senses<input bind:value={sheet.senses} placeholder="visão no escuro 18 m"/></label><label>Idiomas<input bind:value={sheet.languages} placeholder="Subcomum"/></label></div>
		<div class="block"><div><h4>Traços</h4><button type="button" onclick={addTrait}>+ Traço</button></div>{#each sheet.traits as trait, index}<article><input bind:value={trait.name} placeholder="Nome do traço"/><textarea bind:value={trait.description} placeholder="Resumo próprio do efeito"></textarea><button type="button" onclick={() => removeTrait(index)}>×</button></article>{/each}</div>
		<div class="block"><div><h4>Ações</h4><button type="button" onclick={addAction}>+ Ação</button></div>{#each sheet.actions as action, index}<article class="action"><input bind:value={action.name} placeholder="Nome"/><select bind:value={action.kind}><option value="action">Ação</option><option value="bonus">Ação bônus</option><option value="reaction">Reação</option></select><input bind:value={action.toHit} type="number" placeholder="Acerto"/><input bind:value={action.damage} placeholder="Dano, ex.: 2d6 veneno"/><input bind:value={action.range} placeholder="Alcance"/><input bind:value={action.saveDC} type="number" min="0" placeholder="CD"/><textarea bind:value={action.description} placeholder="Resumo próprio e objetivo"></textarea><button type="button" onclick={() => removeAction(index)}>×</button></article>{/each}</div>
		<div class="footer"><button class="primary" disabled={saving}>{saving ? 'Salvando…' : selected ? 'Salvar alterações' : 'Adicionar ao bestiário'}</button>{#if selected}<button type="button" class="place" onclick={placeSelected} disabled={placing === selected.id}>{placing === selected.id ? 'Adicionando…' : 'Adicionar à cena'}</button>{/if}</div></form>{/if}</section></section>
</main>

<style>
.bestiary{min-height:520px;padding:clamp(1.25rem,3vw,2.5rem);color:#eee4d6}.bestiary>header{display:flex;justify-content:space-between;gap:1rem;margin-bottom:1.25rem;padding-bottom:1.1rem;border-bottom:1px solid #3b3030}.bestiary header p{margin:0 0 .45rem;color:#d8ad67;font-size:.65rem;font-weight:800;letter-spacing:.14em}.bestiary h2{margin:0 0 .35rem;font:500 clamp(1.8rem,4vw,2.7rem) Georgia,serif}.bestiary header span,.hint,.editor-head span{color:#a99c91;font-size:.8rem}.bestiary>header button,.primary,.place,.block>div button{border:1px solid #765d3d;border-radius:7px;padding:.52rem .7rem;color:#edc77f;background:#2b211e;font-weight:750;cursor:pointer}.message{margin:0 0 1rem;color:#f0cb85;font-size:.8rem}.success{color:#acdba2}.layout{display:grid;grid-template-columns:minmax(190px,.36fr) 1fr;gap:1rem}aside{display:grid;align-content:start;gap:.5rem;border:1px solid #493c39;border-radius:10px;padding:.8rem;background:#211b1e}aside h3{margin:.15rem;font:600 .95rem Georgia,serif}.srd-heading{margin-top:1rem!important;padding-top:1rem;border-top:1px solid #493c39;color:#d8ad67}aside button{display:grid;gap:.2rem;border:1px solid transparent;border-radius:7px;padding:.65rem;color:#e9ddce;background:#2a2222;text-align:left;cursor:pointer}aside button.active,aside button:hover{border-color:#d8ad67}aside small{color:#a99c91;font-size:.67rem}.editor{border:1px solid #5b4938;border-radius:10px;padding:1rem;background:#251e1c}.editor-head{margin-bottom:1rem}.editor h3,.editor h4{margin:0 0 .35rem;font:600 1rem Georgia,serif}.editor h4{margin-top:1.2rem;color:#d8ad67;font-size:.83rem}.srd-preview{display:grid;gap:1rem;max-width:680px;color:#d9cebf;line-height:1.6}.srd-preview small{color:#a99c91}.grid{display:grid;grid-template-columns:repeat(2,minmax(0,1fr));gap:.55rem}.grid label,.abilities label{display:grid;gap:.25rem;color:#b9aa9d;font-size:.67rem}.wide{grid-column:1/-1}.grid input,.abilities input,.block input,.block textarea,.block select{min-width:0;border:1px solid #59483b;border-radius:6px;padding:.5rem;color:#eadfce;background:#161216;font:inherit;font-size:.78rem}.abilities{display:grid;grid-template-columns:repeat(6,1fr);gap:.45rem}.block{margin-top:1rem;padding-top:.9rem;border-top:1px solid #493c39}.block>div{display:flex;align-items:center;justify-content:space-between}.block>div h4{margin:0}.block>div button{padding:.35rem .5rem;font-size:.67rem}.block article{display:grid;grid-template-columns:170px 1fr auto;gap:.45rem;margin-top:.55rem}.block textarea{min-height:48px;resize:vertical}.action{grid-template-columns:1.2fr .8fr .55fr 1.2fr .8fr .55fr auto!important}.action textarea{grid-column:1/-2}.block article>button{border:0;color:#d7b3a5;background:transparent;font-size:1.1rem}.footer{display:flex;justify-content:flex-end;gap:.6rem;margin-top:1.2rem}.primary{border:0;color:#26190e;background:#e0b86f}.place{background:#2b211e}@media(max-width:750px){.layout{grid-template-columns:1fr}.layout aside{max-height:250px;overflow:auto}.abilities{grid-template-columns:repeat(3,1fr)}.action,.block article{grid-template-columns:1fr 1fr!important}.action textarea{grid-column:1/-1}.grid{grid-template-columns:1fr}.wide{grid-column:auto}.bestiary>header{flex-direction:column}}
</style>
